-- ============================================================================
-- AEGIS-ERP - Fase 2: Modulo de Planilla
-- Conversion Oracle del archivo docente Planilla-SQL.sql.
-- IMPORTANTE: revisar y respaldar antes de ejecutar. Este script no se ejecuta
-- automaticamente y reconstruye exclusivamente las 16 tablas de Fase 2.
-- Compatible con Oracle Database 19c/21c (XEPDB1).
-- ============================================================================

SET DEFINE OFF
SET SERVEROUTPUT ON
WHENEVER SQLERROR EXIT SQL.SQLCODE ROLLBACK

-- ============================================================================
-- 1. PREVALIDACIONES
-- Detiene la instalacion antes de cualquier DDL si la Fase 1 o los IDs
-- academicos requeridos no son compatibles con la base instalada.
-- ============================================================================
DECLARE
    V_COUNT NUMBER;

    PROCEDURE REQUIRE_TABLE(P_TABLE VARCHAR2) IS
    BEGIN
        SELECT COUNT(*) INTO V_COUNT FROM USER_TABLES WHERE TABLE_NAME = P_TABLE;
        IF V_COUNT <> 1 THEN
            RAISE_APPLICATION_ERROR(-20001, 'Falta la tabla requerida de Fase 1: ' || P_TABLE);
        END IF;
    END;

    PROCEDURE REQUIRE_IDENTITY(P_TABLE VARCHAR2, P_COLUMN VARCHAR2) IS
    BEGIN
        SELECT COUNT(*) INTO V_COUNT
          FROM USER_TAB_IDENTITY_COLS
         WHERE TABLE_NAME = P_TABLE
           AND COLUMN_NAME = P_COLUMN
           AND GENERATION_TYPE LIKE 'BY DEFAULT%';
        IF V_COUNT <> 1 THEN
            RAISE_APPLICATION_ERROR(-20002,
                'La columna ' || P_TABLE || '.' || P_COLUMN ||
                ' debe ser IDENTITY BY DEFAULT para aceptar el ID academico.');
        END IF;
    END;

    PROCEDURE REQUIRE_COLUMN(
        P_TABLE VARCHAR2, P_COLUMN VARCHAR2, P_DATA_TYPE VARCHAR2) IS
        V_ACTUAL_TYPE USER_TAB_COLUMNS.DATA_TYPE%TYPE;
        V_EXPECTED_TYPE VARCHAR2(128) := UPPER(TRIM(P_DATA_TYPE));
        V_COMPATIBLE BOOLEAN := FALSE;
    BEGIN
        SELECT UPPER(TRIM(DATA_TYPE)) INTO V_ACTUAL_TYPE
          FROM USER_TAB_COLUMNS
         WHERE TABLE_NAME = P_TABLE
           AND COLUMN_NAME = P_COLUMN;

        -- Oracle 21c publica un TIMESTAMP sin precision explicita del DDL como
        -- TIMESTAMP(6) en USER_TAB_COLUMNS.DATA_TYPE. Ambos representan el
        -- TIMESTAMP definido en ERP.sql; no se aceptan variantes WITH TIME ZONE.
        IF V_EXPECTED_TYPE = 'TIMESTAMP' THEN
            V_COMPATIBLE := V_ACTUAL_TYPE IN ('TIMESTAMP', 'TIMESTAMP(6)');
        ELSE
            -- NUMBER, VARCHAR2, CHAR y DATE se publican por su nombre base;
            -- precision, escala y longitud se encuentran en columnas separadas.
            V_COMPATIBLE := V_ACTUAL_TYPE = V_EXPECTED_TYPE;
        END IF;

        IF NOT V_COMPATIBLE THEN
            RAISE_APPLICATION_ERROR(-20008,
                'Columna incompatible o inexistente: ' || P_TABLE || '.' || P_COLUMN ||
                ' debe ser ' || V_EXPECTED_TYPE ||
                ' y Oracle reporta ' || V_ACTUAL_TYPE || '.');
        END IF;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            RAISE_APPLICATION_ERROR(-20008,
                'Columna incompatible o inexistente: ' || P_TABLE || '.' || P_COLUMN ||
                ' debe ser ' || V_EXPECTED_TYPE || ' y no existe en USER_TAB_COLUMNS.');
    END;

    PROCEDURE REQUIRE_SINGLE_KEY(P_TABLE VARCHAR2, P_COLUMN VARCHAR2) IS
    BEGIN
        SELECT COUNT(*) INTO V_COUNT
          FROM USER_CONSTRAINTS C
          JOIN USER_CONS_COLUMNS CC
            ON CC.CONSTRAINT_NAME = C.CONSTRAINT_NAME
           AND CC.TABLE_NAME = C.TABLE_NAME
         WHERE C.TABLE_NAME = P_TABLE
           AND C.CONSTRAINT_TYPE IN ('P', 'U')
           AND C.STATUS = 'ENABLED'
           AND CC.COLUMN_NAME = P_COLUMN
           AND (SELECT COUNT(*)
                  FROM USER_CONS_COLUMNS ALL_CC
                 WHERE ALL_CC.CONSTRAINT_NAME = C.CONSTRAINT_NAME
                   AND ALL_CC.TABLE_NAME = C.TABLE_NAME) = 1;
        IF V_COUNT < 1 THEN
            RAISE_APPLICATION_ERROR(-20009,
                'Falta PK/UK simple requerida sobre ' || P_TABLE || '.' || P_COLUMN || '.');
        END IF;
    END;

    PROCEDURE ASSERT_FREE_ID(
        P_TABLE VARCHAR2, P_COLUMN VARCHAR2, P_ID NUMBER, P_LABEL VARCHAR2) IS
    BEGIN
        EXECUTE IMMEDIATE
            'SELECT COUNT(*) FROM ' || DBMS_ASSERT.SQL_OBJECT_NAME(P_TABLE) ||
            ' WHERE ' || DBMS_ASSERT.SIMPLE_SQL_NAME(P_COLUMN) || ' = :1'
            INTO V_COUNT USING P_ID;
        IF V_COUNT > 0 THEN
            RAISE_APPLICATION_ERROR(-20003,
                'Colision de ID: ' || P_LABEL || ' requiere ' || P_TABLE || '.' ||
                P_COLUMN || '=' || P_ID || ', pero ya esta ocupado.');
        END IF;
    END;

    PROCEDURE ASSERT_REFERENCE(
        P_TABLE VARCHAR2, P_COLUMN VARCHAR2, P_ID NUMBER, P_LABEL VARCHAR2) IS
    BEGIN
        EXECUTE IMMEDIATE
            'SELECT COUNT(*) FROM ' || DBMS_ASSERT.SQL_OBJECT_NAME(P_TABLE) ||
            ' WHERE ' || DBMS_ASSERT.SIMPLE_SQL_NAME(P_COLUMN) || ' = :1'
            INTO V_COUNT USING P_ID;
        IF V_COUNT <> 1 THEN
            RAISE_APPLICATION_ERROR(-20004,
                'Dato requerido no encontrado: ' || P_LABEL || ' (' || P_TABLE || '.' ||
                P_COLUMN || '=' || P_ID || ').');
        END IF;
    END;
BEGIN
    FOR T IN (
        SELECT COLUMN_VALUE TABLE_NAME
          FROM TABLE(SYS.ODCIVARCHAR2LIST(
              'EMPRESA','GENERO','SUCURSAL','MODULO','MENU','OPCION','ROLE','ROLE_OPCION'))
    ) LOOP
        REQUIRE_TABLE(T.TABLE_NAME);
    END LOOP;

    REQUIRE_IDENTITY('MODULO', 'ID_MODULO');
    REQUIRE_IDENTITY('MENU', 'ID_MENU');
    REQUIRE_IDENTITY('OPCION', 'ID_OPCION');

    REQUIRE_COLUMN('EMPRESA', 'ID_EMPRESA', 'NUMBER');
    REQUIRE_COLUMN('GENERO', 'ID_GENERO', 'NUMBER');
    REQUIRE_COLUMN('SUCURSAL', 'ID_SUCURSAL', 'NUMBER');
    REQUIRE_COLUMN('MODULO', 'ID_MODULO', 'NUMBER');
    REQUIRE_COLUMN('MODULO', 'NOMBRE', 'VARCHAR2');
    REQUIRE_COLUMN('MODULO', 'ORDEN_MENU', 'NUMBER');
    REQUIRE_COLUMN('MODULO', 'FECHA_CREACION', 'TIMESTAMP');
    REQUIRE_COLUMN('MODULO', 'USUARIO_CREACION', 'VARCHAR2');
    REQUIRE_COLUMN('MENU', 'ID_MENU', 'NUMBER');
    REQUIRE_COLUMN('MENU', 'ID_MODULO', 'NUMBER');
    REQUIRE_COLUMN('MENU', 'NOMBRE', 'VARCHAR2');
    REQUIRE_COLUMN('MENU', 'ORDEN_MENU', 'NUMBER');
    REQUIRE_COLUMN('MENU', 'FECHA_CREACION', 'TIMESTAMP');
    REQUIRE_COLUMN('MENU', 'USUARIO_CREACION', 'VARCHAR2');
    REQUIRE_COLUMN('OPCION', 'ID_OPCION', 'NUMBER');
    REQUIRE_COLUMN('OPCION', 'ID_MENU', 'NUMBER');
    REQUIRE_COLUMN('OPCION', 'NOMBRE', 'VARCHAR2');
    REQUIRE_COLUMN('OPCION', 'ORDEN_MENU', 'NUMBER');
    REQUIRE_COLUMN('OPCION', 'PAGINA', 'VARCHAR2');
    REQUIRE_COLUMN('OPCION', 'FECHA_CREACION', 'TIMESTAMP');
    REQUIRE_COLUMN('OPCION', 'USUARIO_CREACION', 'VARCHAR2');
    REQUIRE_COLUMN('ROLE', 'ID_ROLE', 'NUMBER');
    REQUIRE_COLUMN('ROLE', 'NOMBRE', 'VARCHAR2');
    REQUIRE_COLUMN('ROLE_OPCION', 'ID_ROLE', 'NUMBER');
    REQUIRE_COLUMN('ROLE_OPCION', 'ID_OPCION', 'NUMBER');
    REQUIRE_COLUMN('ROLE_OPCION', 'CONSULTAR', 'NUMBER');
    REQUIRE_COLUMN('ROLE_OPCION', 'ALTA', 'NUMBER');
    REQUIRE_COLUMN('ROLE_OPCION', 'BAJA', 'NUMBER');
    REQUIRE_COLUMN('ROLE_OPCION', 'CAMBIO', 'NUMBER');
    REQUIRE_COLUMN('ROLE_OPCION', 'IMPRIMIR', 'NUMBER');
    REQUIRE_COLUMN('ROLE_OPCION', 'EXPORTAR', 'NUMBER');
    REQUIRE_COLUMN('ROLE_OPCION', 'FECHA_CREACION', 'TIMESTAMP');
    REQUIRE_COLUMN('ROLE_OPCION', 'USUARIO_CREACION', 'VARCHAR2');

    REQUIRE_SINGLE_KEY('EMPRESA', 'ID_EMPRESA');
    REQUIRE_SINGLE_KEY('GENERO', 'ID_GENERO');
    REQUIRE_SINGLE_KEY('SUCURSAL', 'ID_SUCURSAL');
    REQUIRE_SINGLE_KEY('MODULO', 'ID_MODULO');
    REQUIRE_SINGLE_KEY('MENU', 'ID_MENU');
    REQUIRE_SINGLE_KEY('OPCION', 'ID_OPCION');
    REQUIRE_SINGLE_KEY('ROLE', 'ID_ROLE');

    ASSERT_REFERENCE('EMPRESA', 'ID_EMPRESA', 1, 'Empresa de los datos docentes');
    ASSERT_REFERENCE('GENERO', 'ID_GENERO', 1, 'Genero 1 de los datos docentes');
    ASSERT_REFERENCE('GENERO', 'ID_GENERO', 2, 'Genero 2 de los datos docentes');
    ASSERT_REFERENCE('SUCURSAL', 'ID_SUCURSAL', 1, 'Sucursal de los datos docentes');

    ASSERT_FREE_ID('MODULO', 'ID_MODULO', 2, 'Modulo Planilla');
    FOR I IN 5..8 LOOP ASSERT_FREE_ID('MENU', 'ID_MENU', I, 'Menu de Planilla'); END LOOP;
    FOR I IN 11..26 LOOP ASSERT_FREE_ID('OPCION', 'ID_OPCION', I, 'Opcion de Planilla'); END LOOP;

    SELECT COUNT(*) INTO V_COUNT FROM MODULO WHERE UPPER(TRIM(NOMBRE)) = 'PLANILLA';
    IF V_COUNT > 0 THEN
        RAISE_APPLICATION_ERROR(-20005, 'Ya existe un modulo llamado Planilla.');
    END IF;

    SELECT COUNT(*) INTO V_COUNT
      FROM OPCION
     WHERE LOWER(REGEXP_REPLACE(TRIM(PAGINA), '\.php$', '')) IN (
         'estado_civil','status_empleado','flujo_status_empleado','tipos_documento',
         'departamento','puesto','personas','documento_persona','banco','empleado',
         'cuenta_bancaria_empleado','inasistencia','calculo_planilla',
         'reporte_planilla','boleta_pago','liquidacion');
    IF V_COUNT > 0 THEN
        RAISE_APPLICATION_ERROR(-20006,
            'Ya existe una o mas paginas logicas reservadas para Planilla.');
    END IF;

    SELECT COUNT(*) INTO V_COUNT FROM ROLE WHERE UPPER(TRIM(NOMBRE)) = 'ADMINISTRADOR';
    IF V_COUNT <> 1 THEN
        RAISE_APPLICATION_ERROR(-20007,
            'Debe existir exactamente un ROLE con nombre Administrador.');
    END IF;

    DBMS_OUTPUT.PUT_LINE('Prevalidaciones completadas correctamente.');
END;
/

-- ============================================================================
-- 2. DROP CONTROLADO DE TABLAS DE FASE 2
-- No elimina ni recrea tablas de Fase 1. El orden respeta las dependencias.
-- ============================================================================
DECLARE
    PROCEDURE DROP_PHASE2_TABLE(P_TABLE VARCHAR2) IS
    BEGIN
        EXECUTE IMMEDIATE 'DROP TABLE ' || DBMS_ASSERT.SIMPLE_SQL_NAME(P_TABLE) ||
                          ' CASCADE CONSTRAINTS PURGE';
    EXCEPTION
        WHEN OTHERS THEN
            IF SQLCODE <> -942 THEN RAISE; END IF;
    END;
BEGIN
    DROP_PHASE2_TABLE('LIQUIDACION');
    DROP_PHASE2_TABLE('PLANILLA_DETALLE');
    DROP_PHASE2_TABLE('PLANILLA_CABECERA');
    DROP_PHASE2_TABLE('PERIODO_PLANILLA');
    DROP_PHASE2_TABLE('INASISTENCIA');
    DROP_PHASE2_TABLE('CUENTA_BANCARIA_EMPLEADO');
    DROP_PHASE2_TABLE('EMPLEADO');
    DROP_PHASE2_TABLE('BANCO');
    DROP_PHASE2_TABLE('PUESTO');
    DROP_PHASE2_TABLE('DOCUMENTO_PERSONA');
    DROP_PHASE2_TABLE('PERSONA');
    DROP_PHASE2_TABLE('TIPO_DOCUMENTO');
    DROP_PHASE2_TABLE('ESTADO_CIVIL');
    DROP_PHASE2_TABLE('DEPARTAMENTO');
    DROP_PHASE2_TABLE('FLUJO_STATUS_EMPLEADO');
    DROP_PHASE2_TABLE('STATUS_EMPLEADO');
END;
/

-- ============================================================================
-- 3. CREATE TABLE
-- Se conserva la nulabilidad y estructura conceptual entregada por el docente.
-- ============================================================================
CREATE TABLE STATUS_EMPLEADO (
    ID_STATUS_EMPLEADO NUMBER GENERATED BY DEFAULT AS IDENTITY,
    NOMBRE VARCHAR2(50),
    FECHA_CREACION TIMESTAMP NOT NULL,
    USUARIO_CREACION VARCHAR2(100) NOT NULL,
    FECHA_MODIFICACION TIMESTAMP,
    USUARIO_MODIFICACION VARCHAR2(100)
);

CREATE TABLE FLUJO_STATUS_EMPLEADO (
    ID_STATUS_ACTUAL NUMBER NOT NULL,
    ID_STATUS_NUEVO NUMBER NOT NULL,
    NOMBRE_EVENTO VARCHAR2(50),
    FECHA_CREACION TIMESTAMP NOT NULL,
    USUARIO_CREACION VARCHAR2(100) NOT NULL,
    FECHA_MODIFICACION TIMESTAMP,
    USUARIO_MODIFICACION VARCHAR2(100)
);

CREATE TABLE DEPARTAMENTO (
    ID_DEPARTAMENTO NUMBER GENERATED BY DEFAULT AS IDENTITY,
    NOMBRE VARCHAR2(50),
    ID_EMPRESA NUMBER,
    FECHA_CREACION TIMESTAMP NOT NULL,
    USUARIO_CREACION VARCHAR2(100) NOT NULL,
    FECHA_MODIFICACION TIMESTAMP,
    USUARIO_MODIFICACION VARCHAR2(100)
);

CREATE TABLE ESTADO_CIVIL (
    ID_ESTADO_CIVIL NUMBER GENERATED BY DEFAULT AS IDENTITY,
    NOMBRE VARCHAR2(50) NOT NULL,
    FECHA_CREACION TIMESTAMP NOT NULL,
    USUARIO_CREACION VARCHAR2(100) NOT NULL,
    FECHA_MODIFICACION TIMESTAMP,
    USUARIO_MODIFICACION VARCHAR2(100)
);

CREATE TABLE TIPO_DOCUMENTO (
    ID_TIPO_DOCUMENTO NUMBER GENERATED BY DEFAULT AS IDENTITY,
    NOMBRE VARCHAR2(50) NOT NULL,
    FECHA_CREACION TIMESTAMP NOT NULL,
    USUARIO_CREACION VARCHAR2(100) NOT NULL,
    FECHA_MODIFICACION TIMESTAMP,
    USUARIO_MODIFICACION VARCHAR2(100)
);

CREATE TABLE PERSONA (
    ID_PERSONA NUMBER GENERATED BY DEFAULT AS IDENTITY,
    NOMBRE VARCHAR2(50) NOT NULL,
    APELLIDO VARCHAR2(50) NOT NULL,
    FECHA_NACIMIENTO DATE NOT NULL,
    ID_GENERO NUMBER NOT NULL,
    DIRECCION VARCHAR2(100) NOT NULL,
    TELEFONO VARCHAR2(50) NOT NULL,
    CORREO_ELECTRONICO VARCHAR2(50),
    ID_ESTADO_CIVIL NUMBER NOT NULL,
    FECHA_CREACION TIMESTAMP NOT NULL,
    USUARIO_CREACION VARCHAR2(100) NOT NULL,
    FECHA_MODIFICACION TIMESTAMP,
    USUARIO_MODIFICACION VARCHAR2(100)
);

CREATE TABLE DOCUMENTO_PERSONA (
    ID_TIPO_DOCUMENTO NUMBER NOT NULL,
    ID_PERSONA NUMBER NOT NULL,
    NO_DOCUMENTO VARCHAR2(50),
    FECHA_CREACION TIMESTAMP NOT NULL,
    USUARIO_CREACION VARCHAR2(100) NOT NULL,
    FECHA_MODIFICACION TIMESTAMP,
    USUARIO_MODIFICACION VARCHAR2(100)
);

CREATE TABLE PUESTO (
    ID_PUESTO NUMBER GENERATED BY DEFAULT AS IDENTITY,
    NOMBRE VARCHAR2(50) NOT NULL,
    ID_DEPARTAMENTO NUMBER NOT NULL,
    FECHA_CREACION TIMESTAMP NOT NULL,
    USUARIO_CREACION VARCHAR2(100) NOT NULL,
    FECHA_MODIFICACION TIMESTAMP,
    USUARIO_MODIFICACION VARCHAR2(100)
);

CREATE TABLE BANCO (
    ID_BANCO NUMBER GENERATED BY DEFAULT AS IDENTITY,
    NOMBRE VARCHAR2(50) NOT NULL,
    FECHA_CREACION TIMESTAMP NOT NULL,
    USUARIO_CREACION VARCHAR2(100) NOT NULL,
    FECHA_MODIFICACION TIMESTAMP,
    USUARIO_MODIFICACION VARCHAR2(100)
);

CREATE TABLE EMPLEADO (
    ID_EMPLEADO NUMBER GENERATED BY DEFAULT AS IDENTITY,
    ID_PERSONA NUMBER NOT NULL,
    ID_SUCURSAL NUMBER NOT NULL,
    FECHA_CONTRATACION DATE NOT NULL,
    ID_PUESTO NUMBER NOT NULL,
    ID_STATUS_EMPLEADO NUMBER NOT NULL,
    INGRESO_SUELDO_BASE NUMBER(10,2) NOT NULL,
    INGRESO_BONIFICACION_DECRETO NUMBER(10,2) NOT NULL,
    INGRESO_OTROS_INGRESOS NUMBER(10,2) NOT NULL,
    DESCUENTO_IGSS NUMBER(10,2) NOT NULL,
    DESCUENTO_ISR NUMBER(10,2) NOT NULL,
    DESCUENTO_INASISTENCIAS NUMBER(10,2) NOT NULL,
    FECHA_CREACION TIMESTAMP NOT NULL,
    USUARIO_CREACION VARCHAR2(100) NOT NULL,
    FECHA_MODIFICACION TIMESTAMP,
    USUARIO_MODIFICACION VARCHAR2(100)
);

CREATE TABLE CUENTA_BANCARIA_EMPLEADO (
    ID_CUENTA_BANCARIA NUMBER GENERATED BY DEFAULT AS IDENTITY,
    ID_EMPLEADO NUMBER NOT NULL,
    ID_BANCO NUMBER NOT NULL,
    NUMERO_DE_CUENTA VARCHAR2(50) NOT NULL,
    ACTIVA CHAR(1) NOT NULL,
    FECHA_CREACION TIMESTAMP NOT NULL,
    USUARIO_CREACION VARCHAR2(100) NOT NULL,
    FECHA_MODIFICACION TIMESTAMP,
    USUARIO_MODIFICACION VARCHAR2(100)
);

CREATE TABLE INASISTENCIA (
    ID_INASISTENCIA NUMBER GENERATED BY DEFAULT AS IDENTITY,
    ID_EMPLEADO NUMBER NOT NULL,
    FECHA_INICIAL TIMESTAMP NOT NULL,
    FECHA_FINAL TIMESTAMP NOT NULL,
    MOTIVO_INASISTENCIA VARCHAR2(300),
    FECHA_PROCESADO TIMESTAMP,
    FECHA_CREACION TIMESTAMP NOT NULL,
    USUARIO_CREACION VARCHAR2(100) NOT NULL,
    FECHA_MODIFICACION TIMESTAMP,
    USUARIO_MODIFICACION VARCHAR2(100)
);

CREATE TABLE PERIODO_PLANILLA (
    ANIO NUMBER(10) NOT NULL,
    MES NUMBER(10) NOT NULL,
    FECHA_INICIO DATE,
    FECHA_FIN DATE,
    FECHA_CREACION TIMESTAMP NOT NULL,
    USUARIO_CREACION VARCHAR2(100) NOT NULL,
    FECHA_MODIFICACION TIMESTAMP,
    USUARIO_MODIFICACION VARCHAR2(100)
);

CREATE TABLE PLANILLA_CABECERA (
    ANIO NUMBER(10) NOT NULL,
    MES NUMBER(10) NOT NULL,
    TOTAL_INGRESOS NUMBER(10,2),
    TOTAL_DESCUENTOS NUMBER(10,2),
    SALARIO_NETO NUMBER(10,2),
    FECHA_HORA_PROCESADA TIMESTAMP,
    FECHA_CREACION TIMESTAMP NOT NULL,
    USUARIO_CREACION VARCHAR2(100) NOT NULL,
    FECHA_MODIFICACION TIMESTAMP,
    USUARIO_MODIFICACION VARCHAR2(100)
);

CREATE TABLE PLANILLA_DETALLE (
    ID_PLANILLA_DETALLE NUMBER GENERATED BY DEFAULT AS IDENTITY,
    ANIO NUMBER(10) NOT NULL,
    MES NUMBER(10) NOT NULL,
    ID_EMPLEADO NUMBER NOT NULL,
    FECHA_CONTRATACION DATE NOT NULL,
    ID_PUESTO NUMBER NOT NULL,
    ID_STATUS_EMPLEADO NUMBER NOT NULL,
    INGRESO_SUELDO_BASE NUMBER(10,2) NOT NULL,
    INGRESO_BONIFICACION_DECRETO NUMBER(10,2) NOT NULL,
    INGRESO_OTROS_INGRESOS NUMBER(10,2) NOT NULL,
    DESCUENTO_IGSS NUMBER(10,2) NOT NULL,
    DESCUENTO_ISR NUMBER(10,2) NOT NULL,
    DESCUENTO_INASISTENCIAS NUMBER(10,2) NOT NULL,
    SALARIO_NETO NUMBER(10,2),
    FECHA_CREACION TIMESTAMP NOT NULL,
    USUARIO_CREACION VARCHAR2(100) NOT NULL,
    FECHA_MODIFICACION TIMESTAMP,
    USUARIO_MODIFICACION VARCHAR2(100)
);

CREATE TABLE LIQUIDACION (
    ID_LIQUIDACION NUMBER GENERATED BY DEFAULT AS IDENTITY,
    ID_EMPLEADO NUMBER NOT NULL,
    FECHA_CONTRATACION DATE NOT NULL,
    FECHA_EGRESO DATE NOT NULL,
    FECHA_LIQUIDACION DATE NOT NULL,
    MOTIVO_EGRESO VARCHAR2(50),
    ID_PUESTO NUMBER NOT NULL,
    INGRESO_SUELDO_BASE NUMBER(10,2) NOT NULL,
    INGRESO_BONIFICACION_DECRETO NUMBER(10,2) NOT NULL,
    INGRESO_OTROS_INGRESOS NUMBER(10,2) NOT NULL,
    DESCUENTO_IGSS NUMBER(10,2) NOT NULL,
    DESCUENTO_ISR NUMBER(10,2) NOT NULL,
    DESCUENTO_INASISTENCIAS NUMBER(10,2) NOT NULL,
    SALARIO_NETO NUMBER(10,2),
    TOTAL_INGRESOS NUMBER(10,2),
    TOTAL_DESCUENTOS NUMBER(10,2),
    TOTAL_NETO NUMBER(10,2),
    FECHA_CREACION TIMESTAMP NOT NULL,
    USUARIO_CREACION VARCHAR2(100) NOT NULL
);

-- ============================================================================
-- 4. CONSTRAINTS (PK simples y compuestas conservadas)
-- ============================================================================
ALTER TABLE STATUS_EMPLEADO ADD CONSTRAINT PK_STATUS_EMPLEADO PRIMARY KEY (ID_STATUS_EMPLEADO);
ALTER TABLE FLUJO_STATUS_EMPLEADO ADD CONSTRAINT PK_FLUJO_STATUS_EMP PRIMARY KEY (ID_STATUS_ACTUAL, ID_STATUS_NUEVO);
ALTER TABLE DEPARTAMENTO ADD CONSTRAINT PK_DEPARTAMENTO PRIMARY KEY (ID_DEPARTAMENTO);
ALTER TABLE ESTADO_CIVIL ADD CONSTRAINT PK_ESTADO_CIVIL PRIMARY KEY (ID_ESTADO_CIVIL);
ALTER TABLE TIPO_DOCUMENTO ADD CONSTRAINT PK_TIPO_DOCUMENTO PRIMARY KEY (ID_TIPO_DOCUMENTO);
ALTER TABLE PERSONA ADD CONSTRAINT PK_PERSONA PRIMARY KEY (ID_PERSONA);
ALTER TABLE DOCUMENTO_PERSONA ADD CONSTRAINT PK_DOCUMENTO_PERSONA PRIMARY KEY (ID_TIPO_DOCUMENTO, ID_PERSONA);
ALTER TABLE PUESTO ADD CONSTRAINT PK_PUESTO PRIMARY KEY (ID_PUESTO);
ALTER TABLE BANCO ADD CONSTRAINT PK_BANCO PRIMARY KEY (ID_BANCO);
ALTER TABLE EMPLEADO ADD CONSTRAINT PK_EMPLEADO PRIMARY KEY (ID_EMPLEADO);
ALTER TABLE CUENTA_BANCARIA_EMPLEADO ADD CONSTRAINT PK_CUENTA_BANC_EMP PRIMARY KEY (ID_CUENTA_BANCARIA);
ALTER TABLE INASISTENCIA ADD CONSTRAINT PK_INASISTENCIA PRIMARY KEY (ID_INASISTENCIA);
ALTER TABLE PERIODO_PLANILLA ADD CONSTRAINT PK_PERIODO_PLANILLA PRIMARY KEY (ANIO, MES);
ALTER TABLE PLANILLA_CABECERA ADD CONSTRAINT PK_PLANILLA_CABECERA PRIMARY KEY (ANIO, MES);
ALTER TABLE PLANILLA_DETALLE ADD CONSTRAINT PK_PLANILLA_DETALLE PRIMARY KEY (ID_PLANILLA_DETALLE);
ALTER TABLE LIQUIDACION ADD CONSTRAINT PK_LIQUIDACION PRIMARY KEY (ID_LIQUIDACION);

-- ============================================================================
-- 5. FOREIGN KEYS
-- Incluye las referencias a EMPRESA, GENERO y SUCURSAL existentes en Fase 1.
-- ============================================================================
ALTER TABLE FLUJO_STATUS_EMPLEADO ADD CONSTRAINT FK_FLUJO_STATUS_ACTUAL FOREIGN KEY (ID_STATUS_ACTUAL) REFERENCES STATUS_EMPLEADO (ID_STATUS_EMPLEADO);
ALTER TABLE FLUJO_STATUS_EMPLEADO ADD CONSTRAINT FK_FLUJO_STATUS_NUEVO FOREIGN KEY (ID_STATUS_NUEVO) REFERENCES STATUS_EMPLEADO (ID_STATUS_EMPLEADO);
ALTER TABLE DEPARTAMENTO ADD CONSTRAINT FK_DEPARTAMENTO_EMPRESA FOREIGN KEY (ID_EMPRESA) REFERENCES EMPRESA (ID_EMPRESA);
ALTER TABLE PERSONA ADD CONSTRAINT FK_PERSONA_GENERO FOREIGN KEY (ID_GENERO) REFERENCES GENERO (ID_GENERO);
ALTER TABLE PERSONA ADD CONSTRAINT FK_PERSONA_ESTADO_CIVIL FOREIGN KEY (ID_ESTADO_CIVIL) REFERENCES ESTADO_CIVIL (ID_ESTADO_CIVIL);
ALTER TABLE DOCUMENTO_PERSONA ADD CONSTRAINT FK_DOC_PERSONA_TIPO FOREIGN KEY (ID_TIPO_DOCUMENTO) REFERENCES TIPO_DOCUMENTO (ID_TIPO_DOCUMENTO);
ALTER TABLE DOCUMENTO_PERSONA ADD CONSTRAINT FK_DOC_PERSONA_PERSONA FOREIGN KEY (ID_PERSONA) REFERENCES PERSONA (ID_PERSONA);
ALTER TABLE PUESTO ADD CONSTRAINT FK_PUESTO_DEPARTAMENTO FOREIGN KEY (ID_DEPARTAMENTO) REFERENCES DEPARTAMENTO (ID_DEPARTAMENTO);
ALTER TABLE EMPLEADO ADD CONSTRAINT FK_EMPLEADO_PERSONA FOREIGN KEY (ID_PERSONA) REFERENCES PERSONA (ID_PERSONA);
ALTER TABLE EMPLEADO ADD CONSTRAINT FK_EMPLEADO_SUCURSAL FOREIGN KEY (ID_SUCURSAL) REFERENCES SUCURSAL (ID_SUCURSAL);
