ALTER TABLE PLANILLA_DETALLE ADD CONSTRAINT FK_DETALLE_EMPLEADO FOREIGN KEY (ID_EMPLEADO) REFERENCES EMPLEADO (ID_EMPLEADO);
ALTER TABLE PLANILLA_DETALLE ADD CONSTRAINT FK_DETALLE_PUESTO FOREIGN KEY (ID_PUESTO) REFERENCES PUESTO (ID_PUESTO);
ALTER TABLE PLANILLA_DETALLE ADD CONSTRAINT FK_DETALLE_STATUS FOREIGN KEY (ID_STATUS_EMPLEADO) REFERENCES STATUS_EMPLEADO (ID_STATUS_EMPLEADO);
ALTER TABLE LIQUIDACION ADD CONSTRAINT FK_LIQUIDACION_EMPLEADO FOREIGN KEY (ID_EMPLEADO) REFERENCES EMPLEADO (ID_EMPLEADO);
