-- ============================================================================
-- 10. ROLE_OPCION
-- Administrador recibe los seis permisos existentes para las 16 opciones.
-- ============================================================================
INSERT INTO ROLE_OPCION
    (ID_ROLE, ID_OPCION, CONSULTAR, ALTA, BAJA, CAMBIO, IMPRIMIR, EXPORTAR,
     FECHA_CREACION, USUARIO_CREACION)
SELECT R.ID_ROLE, O.ID_OPCION, 1, 1, 1, 1, 1, 1, SYSTIMESTAMP, 'system'
  FROM ROLE R
 CROSS JOIN OPCION O
 WHERE UPPER(TRIM(R.NOMBRE)) = 'ADMINISTRADOR'
   AND O.ID_OPCION BETWEEN 11 AND 26;

COMMIT;

-- Realinea las identities de Fase 1 luego de insertar IDs academicos explicitos.
-- START WITH LIMIT VALUE toma MAX(ID)+1 para identities ascendentes.
ALTER TABLE MODULO MODIFY ID_MODULO GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE MENU MODIFY ID_MENU GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
ALTER TABLE OPCION MODIFY ID_OPCION GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);

-- ============================================================================
-- 11. VALIDACIONES FINALES
-- ============================================================================
DECLARE
    V_COUNT NUMBER;
    PROCEDURE ASSERT_COUNT(P_SQL VARCHAR2, P_EXPECTED NUMBER, P_MESSAGE VARCHAR2) IS
    BEGIN
        EXECUTE IMMEDIATE P_SQL INTO V_COUNT;
        IF V_COUNT <> P_EXPECTED THEN
            RAISE_APPLICATION_ERROR(-20020,
                P_MESSAGE || '. Esperado=' || P_EXPECTED || ', obtenido=' || V_COUNT);
        END IF;
    END;
BEGIN
    ASSERT_COUNT('SELECT COUNT(*) FROM USER_TABLES WHERE TABLE_NAME IN (' ||
        '''STATUS_EMPLEADO'',''FLUJO_STATUS_EMPLEADO'',''DEPARTAMENTO'',''ESTADO_CIVIL'',' ||
        '''TIPO_DOCUMENTO'',''PERSONA'',''DOCUMENTO_PERSONA'',''PUESTO'',''BANCO'',' ||
        '''EMPLEADO'',''CUENTA_BANCARIA_EMPLEADO'',''INASISTENCIA'',''PERIODO_PLANILLA'',' ||
        '''PLANILLA_CABECERA'',''PLANILLA_DETALLE'',''LIQUIDACION'')',
        16, 'No se crearon las 16 tablas de Fase 2');
    ASSERT_COUNT('SELECT COUNT(*) FROM STATUS_EMPLEADO', 5, 'STATUS_EMPLEADO incompleto');
    ASSERT_COUNT('SELECT COUNT(*) FROM FLUJO_STATUS_EMPLEADO', 9, 'FLUJO_STATUS_EMPLEADO incompleto');
    ASSERT_COUNT('SELECT COUNT(*) FROM DEPARTAMENTO', 13, 'DEPARTAMENTO incompleto');
    ASSERT_COUNT('SELECT COUNT(*) FROM ESTADO_CIVIL', 5, 'ESTADO_CIVIL incompleto');
    ASSERT_COUNT('SELECT COUNT(*) FROM TIPO_DOCUMENTO', 5, 'TIPO_DOCUMENTO incompleto');
    ASSERT_COUNT('SELECT COUNT(*) FROM PERSONA', 100, 'PERSONA incompleta');
    ASSERT_COUNT('SELECT COUNT(*) FROM DOCUMENTO_PERSONA', 100, 'DOCUMENTO_PERSONA incompleto');
    ASSERT_COUNT('SELECT COUNT(*) FROM PUESTO', 29, 'PUESTO incompleto');
    ASSERT_COUNT('SELECT COUNT(*) FROM BANCO', 4, 'BANCO incompleto');
    ASSERT_COUNT('SELECT COUNT(*) FROM EMPLEADO', 100, 'EMPLEADO incompleto');
    ASSERT_COUNT('SELECT COUNT(*) FROM CUENTA_BANCARIA_EMPLEADO', 100, 'CUENTA_BANCARIA_EMPLEADO incompleta');
    ASSERT_COUNT('SELECT COUNT(*) FROM INASISTENCIA', 0, 'INASISTENCIA contiene datos no esperados');
    ASSERT_COUNT('SELECT COUNT(*) FROM PERIODO_PLANILLA', 16, 'PERIODO_PLANILLA incompleto');
    ASSERT_COUNT('SELECT COUNT(*) FROM PLANILLA_CABECERA', 0, 'PLANILLA_CABECERA contiene datos no esperados');
    ASSERT_COUNT('SELECT COUNT(*) FROM PLANILLA_DETALLE', 0, 'PLANILLA_DETALLE contiene datos no esperados');
    ASSERT_COUNT('SELECT COUNT(*) FROM LIQUIDACION', 0, 'LIQUIDACION contiene datos no esperados');
    ASSERT_COUNT('SELECT COUNT(*) FROM USER_CONSTRAINTS WHERE TABLE_NAME IN (' ||
        '''STATUS_EMPLEADO'',''FLUJO_STATUS_EMPLEADO'',''DEPARTAMENTO'',''ESTADO_CIVIL'',' ||
        '''TIPO_DOCUMENTO'',''PERSONA'',''DOCUMENTO_PERSONA'',''PUESTO'',''BANCO'',' ||
        '''EMPLEADO'',''CUENTA_BANCARIA_EMPLEADO'',''INASISTENCIA'',''PERIODO_PLANILLA'',' ||
        '''PLANILLA_CABECERA'',''PLANILLA_DETALLE'',''LIQUIDACION'') AND CONSTRAINT_TYPE=''P''',
        16, 'Cantidad de PK de Fase 2 incorrecta');
    ASSERT_COUNT('SELECT COUNT(*) FROM USER_CONSTRAINTS WHERE TABLE_NAME IN (' ||
        '''STATUS_EMPLEADO'',''FLUJO_STATUS_EMPLEADO'',''DEPARTAMENTO'',''ESTADO_CIVIL'',' ||
        '''TIPO_DOCUMENTO'',''PERSONA'',''DOCUMENTO_PERSONA'',''PUESTO'',''BANCO'',' ||
        '''EMPLEADO'',''CUENTA_BANCARIA_EMPLEADO'',''INASISTENCIA'',''PERIODO_PLANILLA'',' ||
        '''PLANILLA_CABECERA'',''PLANILLA_DETALLE'',''LIQUIDACION'') AND CONSTRAINT_TYPE=''R''',
        22, 'Cantidad de FK de Fase 2 incorrecta');
    ASSERT_COUNT('SELECT COUNT(*) FROM MODULO WHERE ID_MODULO=2 AND NOMBRE=''Planilla''', 1, 'Modulo Planilla incorrecto');
    ASSERT_COUNT('SELECT COUNT(*) FROM MENU WHERE ID_MODULO=2 AND ID_MENU BETWEEN 5 AND 8', 4, 'Menus de Planilla incompletos');
    ASSERT_COUNT('SELECT COUNT(*) FROM OPCION WHERE ID_OPCION BETWEEN 11 AND 26', 16, 'Opciones de Planilla incompletas');
    ASSERT_COUNT('SELECT COUNT(*) FROM ROLE_OPCION RO JOIN ROLE R ON R.ID_ROLE=RO.ID_ROLE WHERE UPPER(TRIM(R.NOMBRE))=''ADMINISTRADOR'' AND RO.ID_OPCION BETWEEN 11 AND 26', 16, 'Permisos de Administrador incompletos');

    SELECT COUNT(*) INTO V_COUNT
      FROM USER_CONSTRAINTS
     WHERE TABLE_NAME IN (
         'STATUS_EMPLEADO','FLUJO_STATUS_EMPLEADO','DEPARTAMENTO','ESTADO_CIVIL',
         'TIPO_DOCUMENTO','PERSONA','DOCUMENTO_PERSONA','PUESTO','BANCO','EMPLEADO',
         'CUENTA_BANCARIA_EMPLEADO','INASISTENCIA','PERIODO_PLANILLA',
         'PLANILLA_CABECERA','PLANILLA_DETALLE','LIQUIDACION')
       AND CONSTRAINT_TYPE IN ('P','R')
       AND (STATUS <> 'ENABLED' OR VALIDATED <> 'VALIDATED');
    IF V_COUNT <> 0 THEN
        RAISE_APPLICATION_ERROR(-20021, 'Existen PK/FK deshabilitadas o no validadas.');
    END IF;

    DBMS_OUTPUT.PUT_LINE('FASE2_PLANILLA validada correctamente.');
END;
/

COMMIT;

-- ============================================================================
-- 12. CONSULTAS DE DIAGNOSTICO (SOLO LECTURA)
-- Permiten comprobar manualmente la instalacion en SQL Developer.
-- ============================================================================

-- Debe devolver 16.
SELECT COUNT(*) AS TABLAS_FASE2
  FROM USER_TABLES
 WHERE TABLE_NAME IN (
     'STATUS_EMPLEADO','FLUJO_STATUS_EMPLEADO','DEPARTAMENTO','ESTADO_CIVIL',
     'TIPO_DOCUMENTO','PERSONA','DOCUMENTO_PERSONA','PUESTO','BANCO','EMPLEADO',
     'CUENTA_BANCARIA_EMPLEADO','INASISTENCIA','PERIODO_PLANILLA',
     'PLANILLA_CABECERA','PLANILLA_DETALLE','LIQUIDACION');

-- Conteos esperados: 5,9,13,5,5,100,100,29,4,100,100,0,16,0,0,0.
SELECT 'STATUS_EMPLEADO' TABLA, COUNT(*) REGISTROS FROM STATUS_EMPLEADO
UNION ALL SELECT 'FLUJO_STATUS_EMPLEADO', COUNT(*) FROM FLUJO_STATUS_EMPLEADO
UNION ALL SELECT 'DEPARTAMENTO', COUNT(*) FROM DEPARTAMENTO
UNION ALL SELECT 'ESTADO_CIVIL', COUNT(*) FROM ESTADO_CIVIL
UNION ALL SELECT 'TIPO_DOCUMENTO', COUNT(*) FROM TIPO_DOCUMENTO
UNION ALL SELECT 'PERSONA', COUNT(*) FROM PERSONA
UNION ALL SELECT 'DOCUMENTO_PERSONA', COUNT(*) FROM DOCUMENTO_PERSONA
UNION ALL SELECT 'PUESTO', COUNT(*) FROM PUESTO
UNION ALL SELECT 'BANCO', COUNT(*) FROM BANCO
UNION ALL SELECT 'EMPLEADO', COUNT(*) FROM EMPLEADO
UNION ALL SELECT 'CUENTA_BANCARIA_EMPLEADO', COUNT(*) FROM CUENTA_BANCARIA_EMPLEADO
UNION ALL SELECT 'INASISTENCIA', COUNT(*) FROM INASISTENCIA
UNION ALL SELECT 'PERIODO_PLANILLA', COUNT(*) FROM PERIODO_PLANILLA
UNION ALL SELECT 'PLANILLA_CABECERA', COUNT(*) FROM PLANILLA_CABECERA
UNION ALL SELECT 'PLANILLA_DETALLE', COUNT(*) FROM PLANILLA_DETALLE
UNION ALL SELECT 'LIQUIDACION', COUNT(*) FROM LIQUIDACION;

-- Debe listar 16 PK y conservar el orden de las claves compuestas.
SELECT C.TABLE_NAME,
       C.CONSTRAINT_NAME,
       LISTAGG(CC.COLUMN_NAME, ', ') WITHIN GROUP (ORDER BY CC.POSITION) AS COLUMNAS,
       C.STATUS,
       C.VALIDATED
  FROM USER_CONSTRAINTS C
  JOIN USER_CONS_COLUMNS CC
    ON CC.CONSTRAINT_NAME = C.CONSTRAINT_NAME
   AND CC.TABLE_NAME = C.TABLE_NAME
 WHERE C.CONSTRAINT_TYPE = 'P'
   AND C.TABLE_NAME IN (
       'STATUS_EMPLEADO','FLUJO_STATUS_EMPLEADO','DEPARTAMENTO','ESTADO_CIVIL',
       'TIPO_DOCUMENTO','PERSONA','DOCUMENTO_PERSONA','PUESTO','BANCO','EMPLEADO',
       'CUENTA_BANCARIA_EMPLEADO','INASISTENCIA','PERIODO_PLANILLA',
       'PLANILLA_CABECERA','PLANILLA_DETALLE','LIQUIDACION')
 GROUP BY C.TABLE_NAME, C.CONSTRAINT_NAME, C.STATUS, C.VALIDATED
 ORDER BY C.TABLE_NAME;

-- Debe listar 22 FK con sus columnas origen y destino en el mismo orden.
SELECT C.TABLE_NAME AS TABLA_ORIGEN,
       C.CONSTRAINT_NAME,
       LISTAGG(CC.COLUMN_NAME, ', ') WITHIN GROUP (ORDER BY CC.POSITION) AS COLUMNAS_ORIGEN,
       RC.TABLE_NAME AS TABLA_DESTINO,
       LISTAGG(RCC.COLUMN_NAME, ', ') WITHIN GROUP (ORDER BY RCC.POSITION) AS COLUMNAS_DESTINO,
       C.STATUS,
       C.VALIDATED
  FROM USER_CONSTRAINTS C
  JOIN USER_CONS_COLUMNS CC
    ON CC.CONSTRAINT_NAME = C.CONSTRAINT_NAME
   AND CC.TABLE_NAME = C.TABLE_NAME
  JOIN USER_CONSTRAINTS RC
    ON RC.CONSTRAINT_NAME = C.R_CONSTRAINT_NAME
  JOIN USER_CONS_COLUMNS RCC
    ON RCC.CONSTRAINT_NAME = RC.CONSTRAINT_NAME
   AND RCC.TABLE_NAME = RC.TABLE_NAME
   AND RCC.POSITION = CC.POSITION
 WHERE C.CONSTRAINT_TYPE = 'R'
   AND C.TABLE_NAME IN (
       'STATUS_EMPLEADO','FLUJO_STATUS_EMPLEADO','DEPARTAMENTO','ESTADO_CIVIL',
       'TIPO_DOCUMENTO','PERSONA','DOCUMENTO_PERSONA','PUESTO','BANCO','EMPLEADO',
       'CUENTA_BANCARIA_EMPLEADO','INASISTENCIA','PERIODO_PLANILLA',
       'PLANILLA_CABECERA','PLANILLA_DETALLE','LIQUIDACION')
 GROUP BY C.TABLE_NAME, C.CONSTRAINT_NAME, RC.TABLE_NAME, C.STATUS, C.VALIDATED
 ORDER BY C.TABLE_NAME, C.CONSTRAINT_NAME;

SELECT ID_MODULO, NOMBRE, ORDEN_MENU
  FROM MODULO
 WHERE ID_MODULO = 2;

SELECT ID_MENU, ID_MODULO, NOMBRE, ORDEN_MENU
  FROM MENU
 WHERE ID_MODULO = 2
 ORDER BY ORDEN_MENU;

SELECT O.ID_OPCION, O.ID_MENU, O.NOMBRE, O.ORDEN_MENU, O.PAGINA
  FROM OPCION O
  JOIN MENU M ON M.ID_MENU = O.ID_MENU
 WHERE M.ID_MODULO = 2
 ORDER BY M.ORDEN_MENU, O.ORDEN_MENU;

SELECT R.NOMBRE AS ROLE,
       RO.ID_OPCION,
       RO.CONSULTAR,
       RO.ALTA,
       RO.BAJA,
       RO.CAMBIO,
       RO.IMPRIMIR,
       RO.EXPORTAR
  FROM ROLE_OPCION RO
  JOIN ROLE R ON R.ID_ROLE = RO.ID_ROLE
 WHERE UPPER(TRIM(R.NOMBRE)) = 'ADMINISTRADOR'
   AND RO.ID_OPCION BETWEEN 11 AND 26
 ORDER BY RO.ID_OPCION;
